sealed interface CartNode;
record LineItem(decimal UnitPrice, int Qty) : CartNode;
record Bundle(string Name, IReadOnlyList<CartNode> Children, decimal Discount) : CartNode;

static decimal Tax(CartNode node, decimal rate) => node switch {
    LineItem l => l.UnitPrice * l.Qty * rate,
    Bundle b   => b.Children.Sum(c => Tax(c, rate)) * b.Discount * rate,
    _ => throw new InvalidOperationException($"Unhandled node {node.GetType().Name}"),
};

