class FieldCounter : CSharpSyntaxWalker {
    public int Fields { get; private set; }
    public override void VisitFieldDeclaration(FieldDeclarationSyntax node) {
        Fields++;                              // the operation's state
        base.VisitFieldDeclaration(node);      // keep walking children
    }
}
